(4286569, 618614, 34659, '<td valign="top">WOW..  STUNNING!  The yellows and greens are so unexpected in this otherwise IR image.  Fantastic work.</td>', 'WOW..  STUNNING!  The yellows and greens are so unexpected in this otherwise IR image.  Fantastic work.', '2007-12-03 18:58:38.000000', NULL, 1),
(4286571, 619173, 22301, '<td valign="top">I like the low angle and the waterfall is very nicely exposed, good luck to you</td>', 'I like the low angle and the waterfall is very nicely exposed, good luck to you', '2007-12-03 18:58:49.000000', NULL, 1),
