(4297496, 619153, 84907, '<td valign="top">I am not quite sure the reason for the selective blurring.  I like the image overall.  The only other area I have issue with is the foreground as it appears a bit blown out.</td>', 'I am not quite sure the reason for the selective blurring.  I like the image overall.  The only other area I have issue with is the foreground as it appears a bit blown out.', '2007-12-06 22:06:16.000000', NULL, 1),
(4297499, 617952, 84907, '<td valign="top">This one freaks me out a little bit in a trippy kind of way.  The movement aspect of the photo adds interest.</td>', 'This one freaks me out a little bit in a trippy kind of way.  The movement aspect of the photo adds interest.', '2007-12-06 22:07:50.000000', NULL, 1),
(4297519, 619063, 84907, '<td valign="top">Interesting use of pp on this one.  The outlining is also very interesting and draws lots of attention to the shot.  I like it!</td>', 'Interesting use of pp on this one.  The outlining is also very interesting and draws lots of attention to the shot.  I like it!', '2007-12-06 22:12:15.000000', NULL, 1),
(4297525, 618922, 84907, '<td valign="top">I love all the colors and items of interest in the shot.  I will also say that the same things that are fun and excellent also detract from the major focus.  A nice shot that can seem a bit cluttered.  Still nice job!</td>', 'I love all the colors and items of interest in the shot.  I will also say that the same things that are fun and excellent also detract from the major focus.  A nice shot that can seem a bit cluttered.  Still nice job!', '2007-12-06 22:14:19.000000', NULL, 1),
(4297528, 618318, 84907, '<td valign="top">I like the shot for the challenge.  Nice blur and good use of lighting on the apple.</td>', 'I like the shot for the challenge.  Nice blur and good use of lighting on the apple.', '2007-12-06 22:15:12.000000', NULL, 1),
(4297529, 618949, 84907, '<td valign="top">:)  nice lighting</td>', ':)  nice lighting', '2007-12-06 22:15:37.000000', NULL, 1),
(4297531, 619214, 84907, '<td valign="top">:)  Fun use of offspring!!  :)</td>', ':)  Fun use of offspring!!  :)', '2007-12-06 22:16:23.000000', NULL, 1),
(4297537, 618669, 84907, '<td valign="top">Interesting shot.  I like the peppers quite a bit.  Great background and lighting as well!</td>', 'Interesting shot.  I like the peppers quite a bit.  Great background and lighting as well!', '2007-12-06 22:20:59.000000', NULL, 1),
(4297547, 617171, 84907, '<td valign="top">Very interesting shot.  Curious about this tree and how this shot came to be.</td>', 'Very interesting shot.  Curious about this tree and how this shot came to be.', '2007-12-06 22:24:46.000000', NULL, 1),
(4297550, 616967, 84907, '<td valign="top">I like this shot, but would love to see more of our lovely friend!</td>', 'I like this shot, but would love to see more of our lovely friend!', '2007-12-06 22:25:20.000000', NULL, 1),
(4297553, 619053, 84907, '<td valign="top">The background and border really frame this image well.  Nice lighting as well.</td>', 'The background and border really frame this image well.  Nice lighting as well.', '2007-12-06 22:26:27.000000', NULL, 1),
(4297574, 618948, 84907, '<td valign="top">Of course an interesting take on the challenge and a wonderful shot.</td>', 'Of course an interesting take on the challenge and a wonderful shot.', '2007-12-06 22:31:26.000000', NULL, 1),
(4297584, 618950, 84907, '<td valign="top">Another take on the apple shot.  This is one is a very good shot with great lower light.  Unfortunate for your great shot is that the other shot much like this pops quite a bit more.  That being said this shot stands on its own and should get a good score.  I hope that others vote it that way.</td>', 'Another take on the apple shot.  This is one is a very good shot with great lower light.  Unfortunate for your great shot is that the other shot much like this pops quite a bit more.  That being said this shot stands on its own and should get a good score.  I hope that others vote it that way.', '2007-12-06 22:33:22.000000', NULL, 1),
(4297593, 619173, 84907, '<td valign="top">Very nice shot.  Love the long release.  Just a very very nice shot with excellent range.</td>', 'Very nice shot.  Love the long release.  Just a very very nice shot with excellent range.', '2007-12-06 22:35:11.000000', NULL, 1),
(4297597, 619134, 84907, '<td valign="top">Fun take on the challenge.  I think a little tighter crop on our apple victim might have helped.</td>', 'Fun take on the challenge.  I think a little tighter crop on our apple victim might have helped.', '2007-12-06 22:36:16.000000', NULL, 1),
(4297601, 618661, 84907, '<td valign="top">I like it.  I think it might have been even better if the shot was a night shot.  The lights would have popped more and if you had a couple of the lights in the house on it could have given a very different look to the shot.</td>', 'I like it.  I think it might have been even better if the shot was a night shot.  The lights would have popped more and if you had a couple of the lights in the house on it could have given a very different look to the shot.', '2007-12-06 22:38:01.000000', NULL, 1),
(4297606, 617672, 84907, '<td valign="top">Not sure I know this fairy tale.  The shot is solid but doesn''t have pop.</td>', 'Not sure I know this fairy tale.  The shot is solid but doesn''t have pop.', '2007-12-06 22:40:18.000000', NULL, 1);
