(4297680, 619025, 84907, '<td valign="top">Very nice shot and great use of lighting to make the shot pop.</td>', 'Very nice shot and great use of lighting to make the shot pop.', '2007-12-06 23:13:12.000000', NULL, 1),
(4297684, 619220, 84907, '<td valign="top">Interesting use of pp for coloring or lack of coloring as the case might be.</td>', 'Interesting use of pp for coloring or lack of coloring as the case might be.', '2007-12-06 23:13:49.000000', NULL, 1),
