(4297690, 619243, 84907, '<td valign="top">Very nice job with the light and with the coloring.  Very solid all around image.</td>', 'Very nice job with the light and with the coloring.  Very solid all around image.', '2007-12-06 23:15:27.000000', NULL, 1),
(4297694, 619120, 84907, '<td valign="top">Great concept, and I love the off center orientation giving the shot interest.</td>', 'Great concept, and I love the off center orientation giving the shot interest.', '2007-12-06 23:16:12.000000', NULL, 1),
(4297697, 618752, 84907, '<td valign="top">LOL  :)  Great fairy tale.  Additionally, that figurine is priceless.  :)  The look on the face is AWESOME!</td>', 'LOL  :)  Great fairy tale.  Additionally, that figurine is priceless.  :)  The look on the face is AWESOME!', '2007-12-06 23:17:05.000000', NULL, 1),
(4297702, 618366, 84907, '<td valign="top">I love the colors but my eye gets lost on where central focus is supposed to end up.</td>', 'I love the colors but my eye gets lost on where central focus is supposed to end up.', '2007-12-06 23:17:43.000000', NULL, 1),
(4297710, 619183, 84907, '<td valign="top">:)  very nice clean image.  Great relation to challenge and just very sharp.  I might have liked a black background on this one to make the orange and the sparks pop but that is just me.</td>', ':)  very nice clean image.  Great relation to challenge and just very sharp.  I might have liked a black background on this one to make the orange and the sparks pop but that is just me.', '2007-12-06 23:19:31.000000', NULL, 1),
(4297713, 618856, 84907, '<td valign="top">?? HUH??  Ok The shot is nicely framed with respect to the pelican, but the partial on the sign detracts quite a bit.</td>', '?? HUH??  Ok The shot is nicely framed with respect to the pelican, but the partial on the sign detracts quite a bit.', '2007-12-06 23:20:18.000000', NULL, 1),
(4297714, 618939, 84907, '<td valign="top">:)  I like it.  The background colors muddle the foreground for me a little.</td>', ':)  I like it.  The background colors muddle the foreground for me a little.', '2007-12-06 23:20:46.000000', NULL, 1),
(4297720, 619021, 84907, '<td valign="top">:)  I would have liked to see a bit higher orientation for the camera to see the figurines faces on some of the upturned faces.  But good shot overall.</td>', ':)  I would have liked to see a bit higher orientation for the camera to see the figurines faces on some of the upturned faces.  But good shot overall.', '2007-12-06 23:23:06.000000', NULL, 1),
(4297725, 618753, 84907, '<td valign="top">Nice close shot, but cropping hurts this shot a little in my opinion.</td>', 'Nice close shot, but cropping hurts this shot a little in my opinion.', '2007-12-06 23:23:53.000000', NULL, 1),
(4297727, 618973, 84907, '<td valign="top">Very nice capture and I love the framing on this one.  Just excellent.</td>', 'Very nice capture and I love the framing on this one.  Just excellent.', '2007-12-06 23:24:29.000000', NULL, 1),
(4297730, 619248, 84907, '<td valign="top">Blatant use of cute kids in challenge!  :)  Very nice shot.  Very well set up.  I even love the pinky point by your model.  :)  Excellent choice on the black background as well.  Just a very nice shot.</td>', 'Blatant use of cute kids in challenge!  :)  Very nice shot.  Very well set up.  I even love the pinky point by your model.  :)  Excellent choice on the black background as well.  Just a very nice shot.', '2007-12-06 23:25:49.000000', NULL, 1),
(4297733, 618975, 84907, '<td valign="top">Very nice shot and also fantastic use of pp especially with the dodging and burning.  Fantastic shot.  I hope that voters realize the value of the shot and do not criticize for lack of applicability because this is a great shot that certainly is applicable.</td>', 'Very nice shot and also fantastic use of pp especially with the dodging and burning.  Fantastic shot.  I hope that voters realize the value of the shot and do not criticize for lack of applicability because this is a great shot that certainly is applicable.', '2007-12-06 23:27:11.000000', NULL, 1),
(4297735, 619020, 84907, '<td valign="top">:)  Nice capture.  I like the set up and image.</td>', ':)  Nice capture.  I like the set up and image.', '2007-12-06 23:27:37.000000', NULL, 1),
(4297738, 618981, 84907, '<td valign="top">Gorgeous model on the float, but would love to see you take two steps to 6 steps to the right and cut that building out of the shot.</td>', 'Gorgeous model on the float, but would love to see you take two steps to 6 steps to the right and cut that building out of the shot.', '2007-12-06 23:28:34.000000', NULL, 1),
(4297748, 619048, 84907, '<td valign="top">Great use of lighting on this shot and also great use of the background to enhance rather than take away from the shot.</td>', 'Great use of lighting on this shot and also great use of the background to enhance rather than take away from the shot.', '2007-12-06 23:31:01.000000', NULL, 1),
(4297750, 619226, 84907, '<td valign="top">I really like the texture and depth that this presentation gives.  While this certainly is not the only apple shot, this one presents a ton of creativity by going with a minimal look and tons of great lighting.  An excellent shot and worthy of a great score.  Back after seeing everything to bump up from 8 to 9 EXCELLENT SHOT! Certainly should see the first page in my opinion.</td>', 'I really like the texture and depth that this presentation gives.  While this certainly is not the only apple shot, this one presents a ton of creativity by going with a minimal look and tons of great lighting.  An excellent shot and worthy of a great score.  Back after seeing everything to bump up from 8 to 9 EXCELLENT SHOT! Certainly should see the first page in my opinion.', '2007-12-06 23:31:59.000000', NULL, 1),
(4297809, 619226, 87389, '<td valign="top">Very cool.</td>', 'Very cool.', '2007-12-06 23:52:00.000000', NULL, 1),
(4297902, 619089, 65035, '<td valign="top">I like the composition</td>', 'I like the composition', '2007-12-07 00:16:48.000000', NULL, 1),
(4297909, 619251, 65035, '<td valign="top">Ahhh creative thinking,I like it.</td>', 'Ahhh creative thinking,I like it.', '2007-12-07 00:17:43.000000', NULL, 1),
