(4297935, 619130, 65035, '<td valign="top">This is lovely, I think it might have been worth trying a slightly tighter crop, just so the rose isn''t centered. I''m not sure.</td>', 'This is lovely, I think it might have been worth trying a slightly tighter crop, just so the rose isn''t centered. I''m not sure.', '2007-12-07 00:21:57.000000', NULL, 1),
(4297937, 619146, 65035, '<td valign="top">The tones are beautiful</td>', 'The tones are beautiful', '2007-12-07 00:22:16.000000', NULL, 1),
(4297940, 618922, 65035, '<td valign="top">very cool idea and great colours</td>', 'very cool idea and great colours', '2007-12-07 00:22:54.000000', NULL, 1),
(4297954, 618958, 65035, '<td valign="top">I didn''t even notice the person the first time I looked at this, they look so small. This is a great letterbox and a nice take on the challenge.</td>', 'I didn''t even notice the person the first time I looked at this, they look so small. This is a great letterbox and a nice take on the challenge.', '2007-12-07 00:24:56.000000', NULL, 1),
(4297958, 619220, 65035, '<td valign="top">very cool.</td>', 'very cool.', '2007-12-07 00:25:24.000000', NULL, 1),
