(4297996, 618961, 65035, '<td valign="top">I love the tones and the selective desat and that is one gorgeously fairytaleish dress and just that slight hint of pink in it is lovely.</td>', 'I love the tones and the selective desat and that is one gorgeously fairytaleish dress and just that slight hint of pink in it is lovely.', '2007-12-07 00:42:02.000000', NULL, 1),
(4297998, 619112, 65035, '<td valign="top">Cool idea, I really like the bule bling on the star.</td>', 'Cool idea, I really like the bule bling on the star.', '2007-12-07 00:42:54.000000', NULL, 1),
(4298002, 619219, 65035, '<td valign="top">Great composition and very creepy. I''m lovin'' those fingernails.</td>', 'Great composition and very creepy. I''m lovin'' those fingernails.', '2007-12-07 00:44:27.000000', NULL, 1),
(4298004, 619020, 65035, '<td valign="top">Ooooo that pixie dust is cleverly done.</td>', 'Ooooo that pixie dust is cleverly done.', '2007-12-07 00:45:12.000000', NULL, 1),
(4298046, 618939, 80429, '<td valign="top">this is AMAZING</td>', 'this is AMAZING', '2007-12-07 01:00:44.000000', NULL, 1),
