(4299909, 617171, 67591, '<td valign="top">this one''s pretty neat.</td>', 'this one''s pretty neat.', '2007-12-07 18:53:51.000000', NULL, 1),
(4299962, 619223, 53572, '<td valign="top">subtle, dark and moving.  the angles and depth of tome work really well here.</td>', 'subtle, dark and moving.  the angles and depth of tome work really well here.', '2007-12-07 19:25:07.000000', NULL, 1),
(4299965, 618318, 53572, '<td valign="top">a very nice image, depth of field working very well indeed.  i''m not overly mad on the very yellow flesh of the apple, though.</td>', 'a very nice image, depth of field working very well indeed.  i''m not overly mad on the very yellow flesh of the apple, though.', '2007-12-07 19:25:58.000000', NULL, 1),
(4299972, 619153, 53572, '<td valign="top">dark and threatening, the blur on the left works very well indeed.  it might benefit from a bit more tone in the foreground, but only a small amount - that wide swath of white is bit overpowering</td>', 'dark and threatening, the blur on the left works very well indeed.  it might benefit from a bit more tone in the foreground, but only a small amount - that wide swath of white is bit overpowering', '2007-12-07 19:27:21.000000', NULL, 1),
(4299973, 619064, 53572, '<td valign="top">a fascinating, disorienting image.  the house could be a doll''s house.  the glowing, deep colours work very well indeed.</td>', 'a fascinating, disorienting image.  the house could be a doll''s house.  the glowing, deep colours work very well indeed.', '2007-12-07 19:28:17.000000', NULL, 1),
(4299975, 619052, 53572, '<td valign="top">wonderful colour, play of light, and that gorgeous sweep of the tree, curling around the sun.  great.</td>', 'wonderful colour, play of light, and that gorgeous sweep of the tree, curling around the sun.  great.', '2007-12-07 19:29:00.000000', NULL, 1),
(4299982, 618372, 53572, '<td valign="top">deep and dark, the mist in the forest, with the light behind the trees.  however, the path appears to go to the dark.</td>', 'deep and dark, the mist in the forest, with the light behind the trees.  however, the path appears to go to the dark.', '2007-12-07 19:31:09.000000', NULL, 1),
(4299985, 618736, 53572, '<td valign="top">a nice image, i do like the motes in the shaft of light.  i''m not sure about the lantern - if it''s needed, or if it should be desaturated.</td>', 'a nice image, i do like the motes in the shaft of light.  i''m not sure about the lantern - if it''s needed, or if it should be desaturated.', '2007-12-07 19:34:21.000000', NULL, 1),
(4299986, 619053, 53572, '<td valign="top">simple, spare, and dark.  nice one.</td>', 'simple, spare, and dark.  nice one.', '2007-12-07 19:34:41.000000', NULL, 1),
(4299990, 618939, 53572, '<td valign="top">very good indeed.  i like the acid colours, and story - fab!  princesses don''t turn into frogs often enough!</td>', 'very good indeed.  i like the acid colours, and story - fab!  princesses don''t turn into frogs often enough!', '2007-12-07 19:35:38.000000', NULL, 1),
(4300459, 618805, 31637, '<td valign="top">Excellent for sure! Lighting, Tones and crispness is an A+. Choice of model is good too, even the apple looks good, I feel like I can grab it as if her hand is coming out of my monitor.</td>', 'Excellent for sure! Lighting, Tones and crispness is an A+. Choice of model is good too, even the apple looks good, I feel like I can grab it as if her hand is coming out of my monitor.', '2007-12-07 23:40:05.000000', NULL, 1),
(4300461, 619181, 31637, '<td valign="top">Pretty cool. All the white overblown snow is not a good choice I think.</td>', 'Pretty cool. All the white overblown snow is not a good choice I think.', '2007-12-07 23:40:45.000000', NULL, 1),
(4300464, 618753, 31637, '<td valign="top">Good use of flash. If not, then the morning sun. 6</td>', 'Good use of flash. If not, then the morning sun. 6', '2007-12-07 23:41:20.000000', NULL, 1),
(4300466, 618820, 31637, '<td valign="top">Cool stuff. Reminds me of Link in Zelda.</td>', 'Cool stuff. Reminds me of Link in Zelda.', '2007-12-07 23:41:48.000000', NULL, 1),
(4300469, 618959, 31637, '<td valign="top">Very good emulation, too bad your lighting is flat and colors too.</td>', 'Very good emulation, too bad your lighting is flat and colors too.', '2007-12-07 23:42:39.000000', NULL, 1),
(4300962, 617952, 6771, '<td valign="top">Some people really dig these types of photos: blurred movement, out of focus, and colors shifted to the red.  Sorry, I am not one of them.</td>', 'Some people really dig these types of photos: blurred movement, out of focus, and colors shifted to the red.  Sorry, I am not one of them.', '2007-12-08 05:08:16.000000', NULL, 1),
(4301387, 618372, 63269, '<td valign="top">Very, very beautiful. I love the mist. The point of view is also awesome, and the way the colorful path leads your eyes into the dark, subdued colors of the forest is intriguing.</td>', 'Very, very beautiful. I love the mist. The point of view is also awesome, and the way the colorful path leads your eyes into the dark, subdued colors of the forest is intriguing.', '2007-12-08 10:56:14.000000', NULL, 1),
(4301390, 619165, 63269, '<td valign="top">Nice shot - I like the precision of the details, lighting, and colors.</td>', 'Nice shot - I like the precision of the details, lighting, and colors.', '2007-12-08 10:56:50.000000', NULL, 1),
(4301392, 619106, 63269, '<td valign="top">Neat! A tad more contrast might have helped this to stand out some more.</td>', 'Neat! A tad more contrast might have helped this to stand out some more.', '2007-12-08 10:57:17.000000', NULL, 1),
(4301393, 619130, 63269, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2007-12-08 10:57:28.000000', NULL, 1),
(4301395, 619250, 63269, '<td valign="top">Some more contrast, and even more color would make this really stand out. Nice capture.</td>', 'Some more contrast, and even more color would make this really stand out. Nice capture.', '2007-12-08 10:58:00.000000', NULL, 1),
(4301397, 618716, 63269, '<td valign="top">Pretty! I like the colors.</td>', 'Pretty! I like the colors.', '2007-12-08 10:58:36.000000', NULL, 1),
(4301405, 618958, 63269, '<td valign="top">This doesn''t really grab my attention very much... and I''m not sure what would help to fix that. I would suggest perhaps making this fully black and white, and perhaps adding more contrast. Personally, I would have also played around with some burning and dodging to bring out those nice tones, but maybe that''s just me... Perhaps a differnt point of view, or a different composition? I don''t know. Good try though! Those tracks and patterns are intriguing. :)</td>', 'This doesn''t really grab my attention very much... and I''m not sure what would help to fix that. I would suggest perhaps making this fully black and white, and perhaps adding more contrast. Personally, I would have also played around with some burning and dodging to bring out those nice tones, but maybe that''s just me... Perhaps a differnt point of view, or a different composition? I don''t know. Good try though! Those tracks and patterns are intriguing. :)', '2007-12-08 11:02:53.000000', NULL, 1),
(4301406, 619194, 63269, '<td valign="top">I LOVE the rich colors here! Very, very beautiful!</td>', 'I LOVE the rich colors here! Very, very beautiful!', '2007-12-08 11:02:55.000000', NULL, 1),
(4301420, 617952, 63269, '<td valign="top">This might be an interesting idea, with the blur, but there are some things I personally would have fixed... the colors, first of all, are a little wild. Maybe less saturation would help, although perhaps you wanted the wild colors. There is lots of grain as well, which you might be able to fix by lowering the ISO. But then the picture can get too dark... Also, the picture appears rather washed out and overexposed. Overall, I would suggest a lower ISO setting, and a longer shutter-speed, and maybe a tripod or even a table-top or something to keep the camera steady and prevent the picture from getting too blurry. Hope some of that was helpful! :)</td>', 'This might be an interesting idea, with the blur, but there are some things I personally would have fixed... the colors, first of all, are a little wild. Maybe less saturation would help, although perhaps you wanted the wild colors. There is lots of grain as well, which you might be able to fix by lowering the ISO. But then the picture can get too dark... Also, the picture appears rather washed out and overexposed. Overall, I would suggest a lower ISO setting, and a longer shutter-speed, and maybe a tripod or even a table-top or something to keep the camera steady and prevent the picture from getting too blurry. Hope some of that was helpful! :)', '2007-12-08 11:12:38.000000', NULL, 1),
(4301433, 618820, 63269, '<td valign="top">Interesting idea. Something about the contrast looks wrong here, though. For example, what should be white on the boy''s shirt is actually a sort of burnt, flat gray. If there were any way to fix that, that would increase the impact of the photo. Good try though, those shadows on the tower create a really neat effect!</td>', 'Interesting idea. Something about the contrast looks wrong here, though. For example, what should be white on the boy''s shirt is actually a sort of burnt, flat gray. If there were any way to fix that, that would increase the impact of the photo. Good try though, those shadows on the tower create a really neat effect!', '2007-12-08 11:22:28.000000', NULL, 1),
(4301435, 619243, 63269, '<td valign="top">The colors here are beautiful, soft and gentle in the sky. Neat shot!</td>', 'The colors here are beautiful, soft and gentle in the sky. Neat shot!', '2007-12-08 11:23:00.000000', NULL, 1),
(4301436, 619248, 63269, '<td valign="top">Good photo!</td>', 'Good photo!', '2007-12-08 11:23:23.000000', NULL, 1),
(4301439, 617672, 63269, '<td valign="top">The lighting here is great, but that thing off in the corner (a spoon?) is a little confusing. I would suggest rearanging the composition around a bit, and using a different point of view.</td>', 'The lighting here is great, but that thing off in the corner (a spoon?) is a little confusing. I would suggest rearanging the composition around a bit, and using a different point of view.', '2007-12-08 11:25:53.000000', NULL, 1),
(4301440, 619053, 63269, '<td valign="top">Striking! I wonder how this would look against a black bacground? Very neat image!</td>', 'Striking! I wonder how this would look against a black bacground? Very neat image!', '2007-12-08 11:26:32.000000', NULL, 1),
(4301442, 618805, 63269, '<td valign="top">Excellent colors and lighting.</td>', 'Excellent colors and lighting.', '2007-12-08 11:26:58.000000', NULL, 1),
(4301449, 619063, 63269, '<td valign="top">I actually like this. And I have no clue why! :) Something about the colors and the shadow tones, I guess. Would be neat to see it without the filter effect, perhaps. But then again maybe that''s part of what I like about it. :D Cool image!</td>', 'I actually like this. And I have no clue why! :) Something about the colors and the shadow tones, I guess. Would be neat to see it without the filter effect, perhaps. But then again maybe that''s part of what I like about it. :D Cool image!', '2007-12-08 11:30:06.000000', NULL, 1),
(4301450, 619201, 63269, '<td valign="top">Nice colors and lighting.</td>', 'Nice colors and lighting.', '2007-12-08 11:30:35.000000', NULL, 1),
(4301452, 619057, 63269, '<td valign="top">A cool idea, but the point of view is very confusing to me. It makes it look like the whole image is up-side-down, and so it''s hard to figure out what''s going on at first. Otherwise, this is kind of a neat photo. :)</td>', 'A cool idea, but the point of view is very confusing to me. It makes it look like the whole image is up-side-down, and so it''s hard to figure out what''s going on at first. Otherwise, this is kind of a neat photo. :)', '2007-12-08 11:32:05.000000', NULL, 1),
(4301455, 618698, 63269, '<td valign="top">Very cool idea, and great lighting!</td>', 'Very cool idea, and great lighting!', '2007-12-08 11:33:34.000000', NULL, 1),
(4301457, 618949, 63269, '<td valign="top">Beautiful hair! One thing that I might try to fix here though is the highlights. They aren''t really white. Adjusting the levels in photoshop would probably help this out. Nice idea though!</td>', 'Beautiful hair! One thing that I might try to fix here though is the highlights. They aren''t really white. Adjusting the levels in photoshop would probably help this out. Nice idea though!', '2007-12-08 11:34:55.000000', NULL, 1),
(4301458, 618369, 63269, '<td valign="top">Although it looks almost like it might be slightly out of focus, this is very pretty. I really like your use of selective desaturation here.</td>', 'Although it looks almost like it might be slightly out of focus, this is very pretty. I really like your use of selective desaturation here.', '2007-12-08 11:35:33.000000', NULL, 1),
(4301460, 619134, 63269, '<td valign="top">Cool idea, and I love the point of view, and the way she is slightly covered by the branch. Some more contrast and even some more saturation might look really nice here.</td>', 'Cool idea, and I love the point of view, and the way she is slightly covered by the branch. Some more contrast and even some more saturation might look really nice here.', '2007-12-08 11:36:13.000000', NULL, 1),
(4301569, 618698, 82503, '<td valign="top">Great light. One of my favorites in the challenge.</td>', 'Great light. One of my favorites in the challenge.', '2007-12-08 13:19:41.000000', NULL, 1),
(4301639, 619048, 63269, '<td valign="top">beautiful colors and textures.</td>', 'beautiful colors and textures.', '2007-12-08 14:09:43.000000', NULL, 1),
(4301640, 618736, 63269, '<td valign="top">Very neat idea, and well executed!</td>', 'Very neat idea, and well executed!', '2007-12-08 14:10:14.000000', NULL, 1),
(4301642, 618367, 63269, '<td valign="top">Excellent copmosition, texture, colors, and tones. This is a splendid shot!</td>', 'Excellent copmosition, texture, colors, and tones. This is a splendid shot!', '2007-12-08 14:11:19.000000', NULL, 1),
(4301647, 619173, 63269, '<td valign="top">I love it! Beautiful capture!</td>', 'I love it! Beautiful capture!', '2007-12-08 14:12:28.000000', NULL, 1),
(4301648, 616967, 63269, '<td valign="top">This is beautiful. I like the gentle white and grey colors.</td>', 'This is beautiful. I like the gentle white and grey colors.', '2007-12-08 14:13:06.000000', NULL, 1),
(4301657, 619026, 63269, '<td valign="top">Sweet! I love the colors, and something about the washed out shadows actually looks nice here, although maybe just a little bit more contrast might be nice. I love that cat''s expression though, hilarious! :)</td>', 'Sweet! I love the colors, and something about the washed out shadows actually looks nice here, although maybe just a little bit more contrast might be nice. I love that cat''s expression though, hilarious! :)', '2007-12-08 14:16:58.000000', NULL, 1),
