(4303858, 619165, 68599, '<td valign="top">Amazing photography. One of my clear favourites of the challenge. I think we''ll see you on the front page for ribbons :) 10</td>', 'Amazing photography. One of my clear favourites of the challenge. I think we''ll see you on the front page for ribbons :) 10', '2007-12-09 16:43:49.000000', NULL, 1),
(4303871, 619025, 11518, '<td valign="top">Beautiful costume, beautiful composition, beautiful post processing, light is a tad harsh.  This should do well.</td>', 'Beautiful costume, beautiful composition, beautiful post processing, light is a tad harsh.  This should do well.', '2007-12-09 16:53:02.000000', NULL, 1),
(4303875, 618369, 11518, '<td valign="top">Beautiful portrait, well executed concept.  I predict the front page.</td>', 'Beautiful portrait, well executed concept.  I predict the front page.', '2007-12-09 17:00:57.000000', NULL, 1),
(4303877, 619055, 11518, '<td valign="top">Kinda creepy!  But well done portrait.</td>', 'Kinda creepy!  But well done portrait.', '2007-12-09 17:02:39.000000', NULL, 1),
(4303889, 617672, 62249, '<td valign="top">Good detail on the foreground edge of the eggshell. I don''t get the reference, though. Must be a fairy tale I''m unfamiliar with.</td>', 'Good detail on the foreground edge of the eggshell. I don''t get the reference, though. Must be a fairy tale I''m unfamiliar with.', '2007-12-09 17:18:42.000000', NULL, 1),
(4303891, 619020, 62249, '<td valign="top">Cute. Highlights are too harsh.</td>', 'Cute. Highlights are too harsh.', '2007-12-09 17:19:52.000000', NULL, 1),
(4303893, 618820, 62249, '<td valign="top">The sword isn''t visible enough against the tower, but the shadows against the bricks are great.</td>', 'The sword isn''t visible enough against the tower, but the shadows against the bricks are great.', '2007-12-09 17:21:16.000000', NULL, 1),
(4303895, 618973, 62249, '<td valign="top">Nice composition and the water droplets are just right.</td>', 'Nice composition and the water droplets are just right.', '2007-12-09 17:22:12.000000', NULL, 1),
(4303901, 618698, 62249, '<td valign="top">The genie needs a shave ;-), but otherwise a very nice idea, well executed. Backlighting is just right, and amount of detail is just right.</td>', 'The genie needs a shave ;-), but otherwise a very nice idea, well executed. Backlighting is just right, and amount of detail is just right.', '2007-12-09 17:24:07.000000', NULL, 1),
(4303905, 618950, 62249, '<td valign="top">Good DOF. Model doesn''t look wicked enough for the tale, though. The fingernails are too neatly manicured for her to be evil ;-). Still, a nice photo.</td>', 'Good DOF. Model doesn''t look wicked enough for the tale, though. The fingernails are too neatly manicured for her to be evil ;-). Still, a nice photo.', '2007-12-09 17:25:37.000000', NULL, 1),
(4303927, 619063, 62249, '<td valign="top">This has potential, even with the over-the-top postprocessing, but the arrangement of the beans isn''t as interesting as it could be. I think you could do more with this concept.</td>', 'This has potential, even with the over-the-top postprocessing, but the arrangement of the beans isn''t as interesting as it could be. I think you could do more with this concept.', '2007-12-09 17:32:35.000000', NULL, 1),
(4303931, 619220, 62249, '<td valign="top">The contemporary sunglasses blow this concept for me. It''s a decent photo but looks too modern for the fairy tale theme.</td>', 'The contemporary sunglasses blow this concept for me. It''s a decent photo but looks too modern for the fairy tale theme.', '2007-12-09 17:33:47.000000', NULL, 1),
(4303940, 618366, 62249, '<td valign="top">The colors have potential, but the composition is only so-so. Maybe try cropping this differently and work on a better title.</td>', 'The colors have potential, but the composition is only so-so. Maybe try cropping this differently and work on a better title.', '2007-12-09 17:36:30.000000', NULL, 1),
(4303943, 619147, 62249, '<td valign="top">Concept is okay, but shoe in background is too contemporary to be plausible for Hansel &amp; Gretel.</td>', 'Concept is okay, but shoe in background is too contemporary to be plausible for Hansel & Gretel.', '2007-12-09 17:37:21.000000', NULL, 1),
(4303946, 619134, 62249, '<td valign="top">Lighting is too flat and uninteresting. Nice garden, though.</td>', 'Lighting is too flat and uninteresting. Nice garden, though.', '2007-12-09 17:37:52.000000', NULL, 1),
(4303958, 618333, 62249, '<td valign="top">Hooray for Timfy the Too(th Fairy)! You come up with the funniest creative shots. This is a hoot. The tatoo is a master touch, and the pink tutu (tootoo?) over black shorts is just too much.</td>', 'Hooray for Timfy the Too(th Fairy)! You come up with the funniest creative shots. This is a hoot. The tatoo is a master touch, and the pink tutu (tootoo?) over black shorts is just too much.', '2007-12-09 17:42:17.000000', NULL, 1),
(4303987, 618333, 59276, '<td valign="top">Tim, you are going to scar that poor child for life! wonderful job, the black socks are a great touch</td>', 'Tim, you are going to scar that poor child for life! wonderful job, the black socks are a great touch', '2007-12-09 17:58:09.000000', NULL, 1),
