(4304475, 618367, 34462, '<td valign="top">Very nice modern day depiction of a fairy tale. well done.</td>', 'Very nice modern day depiction of a fairy tale. well done.', '2007-12-09 21:33:07.000000', NULL, 1),
(4304476, 618318, 83313, '<td valign="top">Great colors on the apple, and the slightly dried out look of it makes you know she has been like this for a few hours when you found her. Nice touch.</td>', 'Great colors on the apple, and the slightly dried out look of it makes you know she has been like this for a few hours when you found her. Nice touch.', '2007-12-09 21:34:03.000000', NULL, 1),
